CREATE TABLE IF NOT EXISTS emergency_requests (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id TEXT NOT NULL, request_type TEXT NOT NULL, title TEXT NOT NULL, description TEXT NOT NULL, location_label TEXT, latitude DOUBLE PRECISION, longitude DOUBLE PRECISION, contact_note TEXT, status TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open','accepted','in_progress','completed','cancelled')), volunteer_user_id TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());